handles = list(vis.output.get("evidence_handles", []))
for m in [m_container, m_plate]:
    if m.ok:
        for h in m.output.get("evidence_handles", []):
            if h not in handles:
                handles.append(h)

print("Using handles:", handles)

pp = primitives.call(
    name="execute_robotwin2_pick_place",
    arm_tag="left",
    evidence_handles=handles,
    source_actor_label="container",
    target_actor_label="plate",
    pre_grasp_distance=0.1,
    lift_distance=0.1,
    pre_place_distance=0.1,
)
print("pick_place ok:", pp.ok)
if pp.ok:
    print("pick_place output keys:", list(pp.output.keys()))
    for k in ["status", "error", "message", "steps", "success"]:
        if k in pp.output:
            print(k, ":", pp.output[k])
else:
    print("pick_place error:", pp.output)

obs = primitives.call(name="observe_robotwin2_scene", query="post pick place")
if obs.ok:
    print(
        "post actors:", obs.output.get("data", {}).get("actor_evidence", {}).get("002_bowl")
    )
    print(
        "plate actor:",
        obs.output.get("data", {}).get("actor_evidence", {}).get("003_plate"),
    )

